// Generate random directions for ray casting
std::vector<CGALRay> rays;
std::random_device rd;
std::mt19937 gen(rd());
std::uniform_real_distribution<double> dis(0.0, 1.0);

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction
    double x = dis(gen) * 2.0 - 1.0;
    double y = dis(gen) * 2.0 - 1.0;
    double z = dis(gen) * 2.0 - 1.0;
    CGALPoint randomDirection(x, y, z);

    // Normalize the direction
    double length = std::sqrt(x*x + y*y + z*z);
    if (length > CG3_EPSILON) {
        randomDirection = CGALPoint(x/length, y/length, z/length);
    }

    // Create a ray from the point in the random direction
    rays.emplace_back(CGALPoint(p.x(), p.y(), p.z()), randomDirection);
}

// Count intersections for each ray
int totalIntersections = 0;
for (const auto& ray : rays) {
    // Count the number of intersections with the mesh
    totalIntersections += tree.number_intersected_primitives(ray);
}

// If the number of intersections is odd, the point is inside
return (totalIntersections % 2) == 1;

